# ! [feature (proc_macro_hygiene , decl_macro)] # [macro_use] extern crate rocket ; # [get ("/")] fn index () -> String { format ! ("{:?}" , routes ! [index]) } # [get ("/name")] fn name () -> String { let x = & routes ! [name] [0] ; match x . name { Some (y) => y . to_string () , None => "None" . to_string () , } } fn main () { rocket :: ignite () . mount ("/" , routes ! [index , name]) . launch () ; }